<script lang="ts">
 import { onMount } from "svelte";
 import type { Account } from "../account.svelte";
 import { locale, setLanguage } from "../i18n.svelte";
 let {account}:{account:Account}=$props();
 let dialog:HTMLDialogElement;
 let register=$state(false),email=$state(""),password=$state(""),name=$state(""),show=$state(false);
 let deleteStep=$state(false),deletePassword=$state(""),deleteConfirmed=$state(false);
 const en=$derived(locale.language==="en");
 const words=(el:string,eng:string)=>en?eng:el;
 const required=$derived(account.ready&&!account.allowed);
 $effect(()=>{if(!dialog)return;if((account.open||required)&&!dialog.open)dialog.showModal();else if(!account.open&&!required&&dialog.open)dialog.close()});
 onMount(()=>{if(new URLSearchParams(location.search).get("account")==="1")account.open=true});
 function close(){if(!required){account.open=false;account.error="";account.message="";password="";deleteStep=false;deletePassword="";deleteConfirmed=false}}
 async function submit(e:SubmitEvent){e.preventDefault();await account.email(email.trim(),password,name,register);password="";}
</script>
{#if !account.ready}<div class="starting" role="status">{words("Φόρτωση λογαριασμού…","Loading account…")}</div>{/if}
<dialog bind:this={dialog} class="account-dialog" oncancel={e=>{if(required)e.preventDefault();else close()}} onclose={close} aria-labelledby="account-title" aria-describedby="account-intro">
 <div class="account-body">
  <header><span class="logo">ΟΑΣΑ <b>Live</b></span><div class="flags" role="group" aria-label={words("Γλώσσα","Language")}><button type="button" aria-label="Ελληνικά" aria-pressed={!en} onclick={()=>setLanguage("el")}><img src={import.meta.env.BASE_URL+"flags/el.svg"} width="27" height="18" alt="" /></button><button type="button" aria-label="English" aria-pressed={en} onclick={()=>setLanguage("en")}><img src={import.meta.env.BASE_URL+"flags/en.svg"} width="27" height="18" alt="" /></button></div>{#if !required}<button class="close" type="button" onclick={close} aria-label={words("Κλείσιμο","Close")}>×</button>{/if}</header>
  {#if deleteStep && account.user}
   <p class="eyebrow">{words("Ο ΛΟΓΑΡΙΑΣΜΟΣ ΣΟΥ","YOUR ACCOUNT")}</p>
   <h1 id="account-title">{words("Διαγραφή λογαριασμού;","Delete your account?")}</h1>
   <p id="account-intro">{words("Θα διαγραφούν ο λογαριασμός OASA Live, οι αποθηκευμένες επιλογές, η γλώσσα και οι αγαπημένες γραμμές σου από το Firebase. Η ενέργεια δεν αναιρείται.","This permanently deletes your OASA Live account, saved choices, language and favourite lines from Firebase. This cannot be undone.")}</p>
   <p class="hint">{words("Σχόλια που έστειλες ξεχωριστά δεν διαγράφονται εδώ. Μια ελάχιστη καταγραφή διαγραφής εμποδίζει παλιές συνδέσεις να επαναφέρουν τις προτιμήσεις σου.","Feedback sent separately is not deleted here. A minimal deletion record prevents old sessions from restoring your preferences.")}</p>
   <form onsubmit={async e=>{e.preventDefault();if(!deleteConfirmed)return;const removed=await account.deleteAccount(deletePassword);deletePassword="";if(removed){deleteStep=false;deleteConfirmed=false;}}}>
    {#if account.user.providerData.some(provider=>provider.providerId==="password")}
     <label for="delete-password">{words("Ο τρέχων κωδικός σου","Your current password")}</label><input id="delete-password" type="password" autocomplete="current-password" required bind:value={deletePassword} disabled={account.busy}/>
    {:else}<p class="hint">{words("Η Google θα σου ζητήσει να επιβεβαιώσεις ξανά τον λογαριασμό σου.","Google will ask you to confirm your account again.")}</p>{/if}
    <label class="delete-confirm"><input type="checkbox" required bind:checked={deleteConfirmed} disabled={account.busy}/><span>{words("Καταλαβαίνω ότι η διαγραφή είναι μόνιμη.","I understand this deletion is permanent.")}</span></label>
    <button class="danger wide" disabled={account.busy||!deleteConfirmed} type="submit">{account.busy?words("Διαγραφή…","Deleting…"):words("Οριστική διαγραφή λογαριασμού","Permanently delete account")}</button>
    <button class="secondary wide" type="button" disabled={account.busy} onclick={()=>{deleteStep=false;deletePassword="";deleteConfirmed=false;account.error=""}}>{words("Διατήρηση λογαριασμού","Keep my account")}</button>
   </form>
  {:else if account.user&&!account.verified}
   <p class="eyebrow">{words("ΕΝΑ ΑΚΟΜΗ ΒΗΜΑ","ONE MORE STEP")}</p><h1 id="account-title">{words("Επιβεβαίωσε το email σου","Verify your email")}</h1>
   <p id="account-intro">{words("Άνοιξε τον σύνδεσμο επιβεβαίωσης που στείλαμε στο","Open the verification link we sent to")} <strong class="email">{account.user.email}</strong>. {words("Μετά, επέστρεψε εδώ για να συνεχίσεις.","Then return here to continue.")}</p>
   <p class="hint">{words("Έλεγξε και την ανεπιθύμητη αλληλογραφία. Η πρόσβαση και ο συγχρονισμός ενεργοποιούνται μετά την επιβεβαίωση.","Check your spam folder too. Access and syncing unlock after verification.")}</p>
   <button class="primary wide" disabled={account.busy} onclick={()=>account.checkVerification()}>{words("Επιβεβαίωσα το email μου — συνέχεια","I’ve verified my email — continue")}</button>
   <button class="secondary wide" disabled={account.busy} onclick={()=>account.resend()}>{words("Νέο email επιβεβαίωσης","Resend verification email")}</button>
   <button class="link wide" disabled={account.busy} onclick={()=>{deleteStep=true;account.error="";account.message=""}}>{words("Διαγραφή λογαριασμού","Delete account")}</button>
   <button class="link wide" disabled={account.busy} onclick={()=>account.logout()}>{words("Αποσύνδεση / άλλο email","Sign out / use another email")}</button>
  {:else if account.verified}
   <p class="eyebrow">{words("Ο ΛΟΓΑΡΙΑΣΜΟΣ ΣΟΥ","YOUR ACCOUNT")}</p><h1 id="account-title">{words("Οι διαδρομές σου, παντού.","Your journeys, everywhere.")}</h1>
   <p id="account-intro" class="email">{account.user?.displayName || account.user?.email}</p><p class="verified">✓ {words("Επιβεβαιωμένο email","Email verified")}</p>
   {#if account.deletionPending}<p class="error" role="status">{words("Ζητήθηκε διαγραφή και οι προτιμήσεις αφαιρέθηκαν. Ολοκλήρωσε τη διαγραφή ή αποσυνδέσου.","Deletion was requested and preferences were erased. Finish deleting the account or sign out.")}</p>{/if}
   <p>{words("Οι τελευταίες γραμμές, η αφετηρία και ο προορισμός, οι επιλογές Εξερεύνησης και τα πλαίσια συγχρονίζονται στον λογαριασμό σου. Συνδέσου στον ίδιο λογαριασμό στο κινητό και στον υπολογιστή για να συνεχίσεις.","Your latest routes, journey endpoints, Explore selections and panel choices sync with your account. Sign in to the same account on your phone and computer to continue where you left off.")}</p>
   <p role="status">{account.syncStatus==="saved"?words("✓ Οι προτιμήσεις συγχρονίστηκαν","✓ Preferences synced"):account.syncStatus==="offline"?words("Δεν έγινε συγχρονισμός. Οι αλλαγές παραμένουν σε αυτή τη συσκευή.","Sync unavailable. Changes remain on this device."):words("Συγχρονισμός…","Syncing…")}</p>
   {#if account.syncStatus==="offline"}<button class="secondary wide" onclick={()=>account.retry()}>{words("Νέα προσπάθεια συγχρονισμού","Retry sync")}</button>{/if}
   <button class="primary wide" onclick={()=>{if(account.deletionPending)deleteStep=true;else close()}}>{account.deletionPending?words("Ολοκλήρωση διαγραφής","Finish account deletion"):words("Πίσω στον χάρτη","Back to the map")}</button><button class="secondary wide" disabled={account.busy} onclick={()=>account.logout()}>{words("Αποσύνδεση","Sign out")}</button>
   <button class="link wide delete-link" disabled={account.busy} onclick={()=>{deleteStep=true;account.error="";account.message=""}}>{words("Διαγραφή λογαριασμού","Delete account")}</button>
  {:else}
   <p class="eyebrow">{words("ΟΙ ΚΑΘΗΜΕΡΙΝΕΣ ΣΟΥ ΔΙΑΔΡΟΜΕΣ","YOUR EVERYDAY JOURNEYS")}</p>
   <h1 id="account-title">{required?words("Συνδέσου για να συνεχίσεις","Sign in to keep exploring"):register?words("Οι διαδρομές σου, παντού.","Your journeys, everywhere."):words("Καλώς επέστρεψες","Welcome back")}</h1>
   <p id="account-intro">{required?words("Χρησιμοποίησες τις δύο δωρεάν δοκιμές σε αυτή τη συσκευή. Δημιούργησε δωρεάν λογαριασμό ή συνδέσου για να συνεχίσεις.","You’ve used the two previews on this device. Create a free account or sign in to continue."):words("Συνέχισε με τις αποθηκευμένες επιλογές σου σε κάθε συσκευή.","Continue with your saved choices on every device.")}</p>
   <div class="tabs" role="group" aria-label={words("Τρόπος πρόσβασης","Account access")}><button type="button" aria-pressed={!register} onclick={()=>{register=false;account.error="";account.message=""}}>{words("Σύνδεση","Sign in")}</button><button type="button" aria-pressed={register} onclick={()=>{register=true;account.error="";account.message=""}}>{words("Εγγραφή","Register")}</button></div>
   {#if register}
    <fieldset class="preferred-language"><legend>{words("Ποια γλώσσα προτιμάς;","Which language do you prefer?")}</legend>
     <button type="button" aria-pressed={!en} onclick={()=>setLanguage("el")}><img src={import.meta.env.BASE_URL+"flags/el.svg"} width="24" height="16" alt=""/>Ελληνικά</button>
     <button type="button" aria-pressed={en} onclick={()=>setLanguage("en")}><img src={import.meta.env.BASE_URL+"flags/en.svg"} width="24" height="16" alt=""/>English</button>
     <p class="hint">{words("Η επιλογή θα αποθηκευτεί στον λογαριασμό σου μετά την επιβεβαίωση του email.","This choice will be saved to your account after email verification.")}</p>
    </fieldset>
   {/if}
   <button class="google wide" disabled={account.busy} onclick={()=>account.google()}><svg viewBox="0 0 48 48" aria-hidden="true" width="20" height="20"><path fill="#4285F4" d="M43.6 24.5c0-1.5-.1-3-.4-4.5H24v8.5h11a9.4 9.4 0 0 1-4.1 6.2v5.1h6.6c3.9-3.6 6.1-8.9 6.1-15.3"/><path fill="#34A853" d="M24 44c5.5 0 10.1-1.8 13.5-4.9l-6.6-5.1c-1.8 1.2-4.1 1.9-6.9 1.9-5.3 0-9.8-3.6-11.4-8.4H5.8v5.3A20.4 20.4 0 0 0 24 44"/><path fill="#FBBC05" d="M12.6 27.5a12 12 0 0 1 0-7V15.2H5.8a20 20 0 0 0 0 17.6z"/><path fill="#EA4335" d="M24 12.1c3 0 5.6 1 7.7 3l5.7-5.7A19.3 19.3 0 0 0 24 4 20.4 20.4 0 0 0 5.8 15.2l6.8 5.3C14.2 15.7 18.7 12.1 24 12.1"/></svg>{words("Συνέχεια με Google","Continue with Google")}</button>
   <div class="divider">{register?words("ή εγγραφή με email","or register with email"):words("ή σύνδεση με email","or sign in with email")}</div>
   <form onsubmit={submit}>
    {#if register}<label for="account-name">{words("Όνομα (προαιρετικά)","Name (optional)")}</label><input id="account-name" autocomplete="name" maxlength="100" bind:value={name} disabled={account.busy} />{/if}
    <label for="account-email">{words("Διεύθυνση email","Email address")}</label><input id="account-email" type="email" autocomplete="email" inputmode="email" autocapitalize="none" spellcheck="false" required bind:value={email} disabled={account.busy} />
    <label for="account-password">{words("Κωδικός πρόσβασης","Password")}</label><div class="password"><input id="account-password" type={show?"text":"password"} autocomplete={register?"new-password":"current-password"} minlength={register?10:undefined} required bind:value={password} disabled={account.busy} aria-describedby={register?"password-help":undefined} /><button type="button" aria-pressed={show} onclick={()=>show=!show}>{show?words("Απόκρυψη","Hide"):words("Εμφάνιση","Show")}</button></div>
    {#if register}<p class="hint" id="password-help">{words("Τουλάχιστον 10 χαρακτήρες. Θα σου στείλουμε email επιβεβαίωσης πριν συνεχίσεις.","At least 10 characters. We’ll email a verification link before you can continue.")}</p>{:else}<button class="link forgot" type="button" disabled={account.busy} onclick={()=>{if(email.trim())void account.reset(email.trim());else account.error=words("Συμπλήρωσε πρώτα το email σου.","Enter your email address first.")}}>{words("Ξέχασες τον κωδικό;","Forgot password?")}</button>{/if}
    <button class="primary wide" type="submit" disabled={account.busy}>{account.busy?words("Περίμενε…","Please wait…"):register?words("Δημιουργία δωρεάν λογαριασμού","Create my free account"):words("Σύνδεση","Sign in")}</button>
   </form>
   <p class="hint privacy">{words("Ο λογαριασμός OASA Live αποθηκεύει τη γλώσσα, τα αγαπημένα και τις τελευταίες επιλογές σου, μαζί με τις επιλεγμένες τοποθεσίες διαδρομής. Δεν αποθηκεύουμε τις κινήσεις GPS ή ιστορικό διαδρομών.","Your OASA Live account stores your language, favourites and latest choices, including chosen journey locations. We do not store your live GPS movements or a history of journeys.")}</p>
   {#if !required}<button class="link wide" onclick={close}>{words("Συνέχεια δοκιμής χωρίς σύνδεση","Continue preview without signing in")}</button>{/if}
  {/if}
  <div aria-live="polite" role="status">{#if account.message}<p class="notice">{account.message}</p>{/if}</div>
  {#if account.error}<p class="error" role="alert">{account.error}</p>{/if}
  <footer><a href={import.meta.env.BASE_URL+"submit-feedback.html?lang="+locale.language}>{words("Χρειάζεσαι βοήθεια;","Need help?")}</a> · <a href={import.meta.env.BASE_URL+"updates.html?lang="+locale.language}>{words("Τι νέο υπάρχει","What’s new")}</a></footer>
 </div>
</dialog>
<style>
.preferred-language{border:1px solid var(--line);border-radius:12px;padding:12px;margin:18px 0}.preferred-language legend{font-size:13px;font-weight:650;padding:0 5px}.preferred-language button{display:inline-flex;align-items:center;gap:6px;min-height:44px;border:1px solid var(--line);border-radius:8px;background:var(--field);color:var(--ink);padding:8px;margin-right:4px;font-size:13px}.preferred-language button[aria-pressed=true]{border-color:var(--accent);background:#328df522}.preferred-language p{margin:10px 0 0}.delete-confirm{display:flex!important;gap:10px;align-items:center;min-height:44px}.delete-confirm input{width:20px!important;min-height:20px!important;height:20px;flex:none}.danger{background:#b82525;color:white;border:0;margin-top:16px}.delete-link{color:#c74848}

.starting{position:fixed;inset:0;display:grid;place-items:center;color:#dbe7f8;background:#101722;z-index:8}.account-dialog{--bg:#fff;--ink:#172338;--muted:#53637b;--line:#d8e1ed;--accent:#0864cf;--field:#f6f8fc;background:var(--bg);color:var(--ink);border:1px solid var(--line);border-radius:24px;width:min(480px,calc(100% - 24px));max-height:calc(100dvh - 24px);padding:0;box-shadow:0 24px 100px #0005;overscroll-behavior:contain}.account-dialog::backdrop{background:#071426a8;backdrop-filter:blur(6px)}.account-body{padding:28px}.account-dialog header{display:flex;align-items:center;gap:12px}.logo{color:var(--ink);font-weight:850;font-size:17px}.logo b{color:var(--accent)}.flags{display:flex;gap:4px;margin-left:auto}.flags button{min-width:44px;min-height:44px;padding:6px;border-radius:10px;border:1px solid var(--line);background:var(--field)}.flags button[aria-pressed=true]{border-color:var(--accent);background:#0864cf22}.flags img{display:block}.close{border:0;border-radius:50%;background:var(--field);color:var(--muted);font-size:26px;width:44px;height:44px}.eyebrow{font-size:10px;letter-spacing:.13em;font-weight:750;color:var(--muted);margin-top:28px}.account-dialog h1{font-size:clamp(25px,6vw,32px);line-height:1.13;letter-spacing:-.025em;margin:12px 0}.account-dialog p{line-height:1.55}.account-dialog #account-intro{color:var(--muted);font-size:14px}.account-dialog button,.account-dialog input{font:inherit}.account-dialog button{cursor:pointer;touch-action:manipulation}.account-dialog button:disabled{opacity:.6;cursor:wait}.wide{width:100%;min-height:48px;border-radius:10px;padding:12px;font-weight:650}.google{display:flex;align-items:center;justify-content:center;gap:12px;border:1px solid var(--line);background:#fff;color:#263346}.divider{display:flex;align-items:center;gap:12px;margin:20px 0;color:var(--muted);font-size:12px}.divider::before,.divider::after{content:"";height:1px;background:var(--line);flex:1}.tabs{display:flex;padding:4px;background:var(--field);border-radius:12px;margin:24px 0 16px;border:1px solid var(--line)}.tabs button{width:50%;border:0;background:transparent;color:var(--muted);min-height:44px;border-radius:8px;font-weight:650}.tabs button[aria-pressed=true]{background:var(--bg);color:var(--ink);box-shadow:0 2px 6px #0001}.account-dialog label{display:block;font-weight:650;font-size:13px;margin:15px 0 7px}.account-dialog input{box-sizing:border-box;min-width:0;width:100%;min-height:48px;border:1px solid var(--line);border-radius:10px;padding:12px;background:var(--field);color:var(--ink);font-size:16px}.password{display:flex;position:relative}.password input{padding-right:95px}.password button{position:absolute;right:4px;top:4px;bottom:4px;border:0;background:transparent;color:var(--accent);padding:0 10px;font-size:12px;font-weight:650}.account-dialog .primary{background:var(--accent);color:white;border:0;margin-top:16px}.secondary{border:1px solid var(--line);color:var(--ink);background:var(--field);margin-top:12px}.link{border:0;background:transparent;color:var(--accent);font-size:13px}.forgot{display:block;margin:12px 0 0 auto;min-height:36px}.hint{font-size:12px;color:var(--muted)}.privacy{margin-top:20px}.email{overflow-wrap:anywhere}.verified{color:#13814b;font-size:13px}.notice,.error{padding:12px;border-radius:10px;font-size:14px;overflow-wrap:anywhere}.notice{background:#13814b12;color:#13814b}.error{background:#b8252512;color:#b82525}footer{border-top:1px solid var(--line);padding-top:16px;margin-top:16px;font-size:12px;color:var(--muted);text-align:center}footer a{color:var(--accent)}.account-dialog :focus-visible{outline:3px solid #5ca4fa;outline-offset:3px}@media(prefers-color-scheme:dark){.account-dialog{--bg:#151e2c;--ink:#edf3fc;--muted:#a7b8d0;--line:#35445c;--accent:#328df5;--field:#1d293b}.notice{color:#75dba6}.error{color:#ffaca7}}@media(max-width:600px){.account-dialog{width:calc(100% - 16px);max-height:calc(100dvh - 16px);border-radius:18px}.account-body{padding:20px}.account-dialog h1{font-size:28px}.eyebrow{margin-top:22px}}@media(max-width:360px){.account-body{padding:16px}}
</style>
